//iq's pallete ideas
const vec3 a=vec3(0.5,0.5,0.5);
const vec3 b=vec3(0.5,0.5,0.5);
const vec3 c=vec3(0.9,0.95,1.0);
const vec3 d=vec3(0.2,0.1,0.0);
vec3 color(float t){
return a + b*cos(2.0*3.1415*(c*t+d));
}
vec2 field(vec2 uv){
vec2 p1=vec2(0.5);
vec2 p2=vec2(cos(iTime),sin(iTime*1.37))/3.0+0.5;
vec2 p3=vec2(cos(iTime+0.6),sin(iTime*1.37+0.6))/4.0+0.5;
vec2 ou=vec2(0.0);
vec2 to1=p1-uv;
vec2 to2=p2-uv;
vec2 to3=p3-uv;
ou-=normalize(to1)/(dot(to1,to1)+0.5);
ou+=normalize(to2)/(dot(to2,to2)+0.5);
ou+=normalize(to3)/(dot(to3,to3)+0.5);
//ou=ou.yx*vec2(-1.0,1.0);
return ou;
//return normalize(-vec2(uv-0.5).yx*vec2(-1.0,1.0));
}
const float steps=10.0;
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec2 grad=uv;
    vec3 tra=vec3(0.0);
    vec2 fp=field(grad);
    vec2 f=fp;
    for(float i=0.0;i<steps;i++){
    fp=f;
    f=field(grad);
    grad+=(f/steps)*0.02;

    tra+=texture(iChannel0,(grad)*0.25).rgb;

    }
    tra/=steps;
tra.r*=tra.r;
tra.r*=tra.r;

tra.r*=4.0;
  fragColor.rgb=tra.r*vec3(0.996,0.835,0.043);
    fragColor.a=1.0;
}
